item.command:
"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$pairRows = @(Import-Csv -LiteralPath evidence/pairs.csv)
$referenceRows = @(Import-Csv -LiteralPath evidence/reference.csv)
$guideRows = @(Import-Csv -LiteralPath evidence/guide.csv)
$referenceById = @{}
$guideById = @{}
foreach ($row in $referenceRows) { if ($referenceById.ContainsKey($row.pair_id)) { throw '"'Duplicate reference pair' }; "'$referenceById[$row.pair_id] = $row }
foreach ($row in $guideRows) { if ($guideById.ContainsKey($row.pair_id)) { throw '"'Duplicate guide pair' }; "'$guideById[$row.pair_id] = $row }
$pairedRows = @(foreach ($pair in $pairRows) {
  $ref = $referenceById[$pair.pair_id]
  $guide = $guideById[$pair.pair_id]
  if ($null -eq $ref -or $null -eq $guide) { throw '"'Unmatched pair' }
  "'$refSeconds = if ([string]::IsNullOrWhiteSpace($ref.seconds)) { $null } else { [decimal]$ref.seconds }
  $guideSeconds = if ([string]::IsNullOrWhiteSpace($guide.seconds)) { $null } else { [decimal]$guide.seconds }
  $eligible = ($null -ne $refSeconds -and $null -ne $guideSeconds -and $refSeconds -gt 0 -and $guideSeconds -gt 0)
  [pscustomobject]@{ pair_id=$pair.pair_id; volunteer_id=$pair.volunteer_id; first_format=$pair.first_format; reference_seconds=$refSeconds; guide_seconds=$guideSeconds; eligible=$eligible; saved_seconds=$(if ($eligible) { $refSeconds - $guideSeconds } else { $null }); reference_correct=($ref.correct -ceq '"'true'); guide_correct=("'$guide.correct -ceq '"'true'); reference_assisted=("'$ref.assisted -ceq '"'true'); guide_assisted=("'$guide.assisted -ceq '"'true') }
})
"'$eligibleRows = @($pairedRows | Where-Object eligible)
$referenceTotal = ($eligibleRows | Measure-Object -Property reference_seconds -Sum).Sum
$guideTotal = ($eligibleRows | Measure-Object -Property guide_seconds -Sum).Sum
$metrics = [ordered]@{ eligible_time_pairs=$eligibleRows.Count; reference_seconds=$referenceTotal; guide_seconds=$guideTotal; time_saved_seconds=($referenceTotal-$guideTotal); faster_pairs=@($eligibleRows | Where-Object { $_.saved_seconds -gt 0 }).Count; slower_pairs=@($eligibleRows | Where-Object { $_.saved_seconds -lt 0 }).Count; tied_pairs=@($eligibleRows | Where-Object { $_.saved_seconds -eq 0 }).Count; accuracy_pairs=$pairedRows.Count; reference_correct=@($pairedRows | Where-Object reference_correct).Count; guide_correct=@($pairedRows | Where-Object guide_correct).Count }
$orders = @($pairedRows | Group-Object volunteer_id | ForEach-Object { [pscustomobject]@{ volunteer_id=$_.Name; pairs=$_.Count; reference_first=@($_.Group | Where-Object { $_.first_format -eq '"'reference' }).Count; guide_first=@("'$_.Group | Where-Object { $_.first_format -eq '"'guide' }).Count } })
[ordered]@{ metrics="'$metrics; percent_saved=(100*($referenceTotal-$guideTotal)/$referenceTotal); pairs=$pairedRows; volunteer_orders=$orders } | ConvertTo-Json -Depth 6'
